    private void hideBtnActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_hideBtnActionPerformed

        if (isPasswordFieldHidden) {
        passwordField.setEchoChar('\u25cf'); 
        isPasswordFieldHidden = false;
        hideBtn.setText("Hide"); 
    } else {
        passwordField.setEchoChar((char)0);
        isPasswordFieldHidden = true;
        hideBtn.setText("Show");
    }
    }//GEN-LAST:event_hideBtnActionPerformed

    private void BtnConfirmActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BtnConfirmActionPerformed
        // TODO add your handling code here:
        if(isEmpty()){
            String uname = usernameField.getText();
            String upass = String.valueOf(passwordField.getPassword());
            if(uname.equals("admin")&& upass.equals("admin")){
                Dashboard dashboard = new Dashboard();
                dashboard.setVisible(true);
                dashboard.pack();
                this.dispose();  
            } else {
                JOptionPane.showMessageDialog(null, "Usename atau Password Salah", "WARNING", 2);
            }
        }
    }//GEN-LAST:event_BtnConfirmActionPerformed

