    public boolean isEmpty(){
       if(usernameField.getText().isEmpty()){
           JOptionPane.showMessageDialog(null, "Username Tidak ditemukan", "WARNING", 2);
           return false;
       }if(String.valueOf(passwordField.getPassword()).isEmpty()){
           JOptionPane.showMessageDialog(null, "Password Salah", "WARNING", 2);
           return false;
       }
       return true;
    }
